from pathlib import Path
import base64
import subprocess

BASE = "517c1f7c567f089d75bd8f0ab97942201ffc8490"
root = Path.cwd()

def dec(v):
    return base64.b64decode(v.encode("ascii")).decode("utf-8")

def fail(message):
    print(f"ERROR: {message}")
    raise SystemExit(1)

head = subprocess.check_output(
    ["git", "rev-parse", "HEAD"],
    cwd=root,
    text=True,
).strip()

if head != BASE:
    fail(
        f"This patch was built on pushed master {BASE}, "
        f"but local HEAD is {head}. No files were changed."
    )

paths = {
    "guest": root / "app/(portal)/game/components/BreezeLodgingGuestsPanel.tsx",
    "actions": root / "app/(portal)/game/breeze-lodgings-actions.ts",
    "access": root / "lib/breeze-lodgings/access.ts",
    "private_actions": root / "app/(portal)/private-location/actions.ts",
    "popup": root / "components/private-location/private-location-invitation-popup.tsx",
    "lodgings_panel": root / "app/(portal)/game/components/BreezeLodgingsPanel.tsx",
}

for path in paths.values():
    if not path.exists():
        fail(f"Missing required file: {path.relative_to(root)}. No files were changed.")

texts = {k: p.read_text(encoding="utf-8") for k, p in paths.items()}

# Full guest panel replacement is guarded by key Stage 3 strings.
for anchor in [
    "Your rented room",
    "Invite a character",
    "Active guests",
    "Manage ▾",
]:
    if anchor not in texts["guest"]:
        fail(f"Guest panel anchor missing: {anchor}. No files were changed.")

actions = texts["actions"]
start = actions.find(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIGludml0ZUJyZWV6ZUxvZGdpbmdHdWVzdCgKICByb29tSWQ6IHN0cmluZywKICBndWVzdENoYXJhY3RlcklkOiBzdHJpbmcsCikgew=="))
end = actions.find(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIHJlbW92ZUJyZWV6ZUxvZGdpbmdHdWVzdCg="))
if start < 0 or end < 0 or end <= start:
    fail("Could not locate the Breeze invitation action block. No files were changed.")

access = texts["access"]
access_start = access.find(dec("ZXhwb3J0IHR5cGUgQnJlZXplTG9kZ2luZ0d1ZXN0Q2hhcmFjdGVyID0gew=="))
if access_start < 0:
    fail("Could not locate Breeze manage-data types. No files were changed.")

private_actions = texts["private_actions"]
for old in [
    dec("ICAgICAgImlkLCByb29tX2lkLCByZWNpcGllbnRfY2hhcmFjdGVyX2lkLCBzdGF0dXMiLA=="),
    dec(""),
]:
    if private_actions.count(old) != 1:
        fail("Private Location invitation response anchor did not match. No files were changed.")

popup = texts["popup"]
for old, new in [('Private Location invitation', 'Invitation'), ('has invited your character into this private location.', 'has invited your character to enter this location.')]:
    if old not in popup:
        fail(f"Popup wording anchor missing: {old}. No files were changed.")

lodgings_panel = texts["lodgings_panel"]
for old in [
    dec("aW1wb3J0IHsgZm9ybWF0UmVtbmFudHMgfSBmcm9tICJAL2xpYi9lY29ub215L2N1cnJlbmN5Ijs="),
    dec(""),
]:
    if lodgings_panel.count(old) != 1:
        fail("Breeze Lodgings date formatter anchor did not match. No files were changed.")

# Build new contents after all validation.
new_guest = dec("")

new_actions = (
    actions[:start]
    + dec("")
    + actions[end + len(dec("ZXhwb3J0IGFzeW5jIGZ1bmN0aW9uIHJlbW92ZUJyZWV6ZUxvZGdpbmdHdWVzdCg=")):]
)
# invite_new already includes the remove function marker/opening parenthesis.
# Preserve the remainder beginning after the old marker text.

new_access = (
    access[:access_start]
    + dec("")
    + "\n"
)

new_private_actions = private_actions.replace(
    dec("ICAgICAgImlkLCByb29tX2lkLCByZWNpcGllbnRfY2hhcmFjdGVyX2lkLCBzdGF0dXMiLA=="),
    dec("ICAgICAgImlkLCByb29tX2lkLCBpbnZpdGVyX2NoYXJhY3Rlcl9pZCwgcmVjaXBpZW50X2NoYXJhY3Rlcl9pZCwgc3RhdHVzIiw="),
    1,
).replace(
    dec(""),
    dec(""),
    1,
)

new_popup = popup
for old, new in [('Private Location invitation', 'Invitation'), ('has invited your character into this private location.', 'has invited your character to enter this location.')]:
    new_popup = new_popup.replace(old, new)

new_lodgings_panel = lodgings_panel.replace(
    dec("aW1wb3J0IHsgZm9ybWF0UmVtbmFudHMgfSBmcm9tICJAL2xpYi9lY29ub215L2N1cnJlbmN5Ijs="),
    dec("aW1wb3J0IHsgZm9ybWF0UmVtbmFudHMgfSBmcm9tICJAL2xpYi9lY29ub215L2N1cnJlbmN5IjsKaW1wb3J0IHsgZ2V0QXVyZXRoRGF0ZSB9IGZyb20gIkAvbGliL3dvcmxkL2NhbGVuZGFyIjs="),
    1,
).replace(
    dec(""),
    dec(""),
    1,
)

# Final sanity checks.
if "withdrawBreezeLodgingInvitation" not in new_actions:
    fail("Internal patch validation failed before write.")
if "pendingInvitations" not in new_access:
    fail("Internal manage-data validation failed before write.")
if "getAurethDate" not in new_lodgings_panel:
    fail("Internal calendar validation failed before write.")

# Write only now.
paths["guest"].write_text(new_guest, encoding="utf-8")
paths["actions"].write_text(new_actions, encoding="utf-8")
paths["access"].write_text(new_access, encoding="utf-8")
paths["private_actions"].write_text(new_private_actions, encoding="utf-8")
paths["popup"].write_text(new_popup, encoding="utf-8")
paths["lodgings_panel"].write_text(new_lodgings_panel, encoding="utf-8")

print("Patch applied successfully.")
print("Changed files:")
for key in [
    "guest",
    "actions",
    "access",
    "private_actions",
    "popup",
    "lodgings_panel",
]:
    print(" -", paths[key].relative_to(root))
print()
print("No SQL is required: this reuses the existing Private Location invitation table and delivery system.")
print("Next: npm run build")
